//! Meter numeric reflection updates actual attributes and CSS paint.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn meter_numeric_actual_app_pointer_attributes_paint_labels_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-meter-numeric-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}meter{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}meter[value="3"]{background:#cc2244}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}label{position:absolute;left:20px;top:100px}</style><body><label id=label for=meter>Work</label><meter id=meter min=0 max=10 value=2 low=1 high=8 optimum=5>Fallback</meter><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change meter</button><div id=destination></div><script>var x=document.getElementById('meter'),labels=x.labels,label=document.getElementById('label'),attr=x.getAttributeNode('value'),round=0;document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var watch=new MutationObserver(function(){}),focus=document.activeElement;watch.observe(x,{attributes:true,attributeOldValue:true});if(round===0)x.value=3;else if(round===1){x.min=4;x.max=8;x.low=7;x.high=5;x.optimum=99;x.value=12;}else x.removeAttribute('value');var records=watch.takeRecords();if(round===0){if(x.value!==3||x.max!==10||x.min!==0||x.low!==1||x.high!==8||x.optimum!==5||records.length!==1||records[0].oldValue!=='2'||attr.value!=='3'||x.getAttributeNode('value')!==attr)throw 'numeric value setter';}else if(round===1){if(x.value!==8||x.min!==4||x.max!==8||x.low!==7||x.high!==7||x.optimum!==8||records.length!==6||records[0].attributeName!=='min'||records[0].oldValue!=='0'||records[5].oldValue!=='3'||attr.value!=='12')throw 'actual maximum and clamp';}else{if(x.value!==4||x.low!==7||x.high!==7||x.optimum!==8||records.length!==1||records[0].oldValue!=='12'||attr.ownerElement!==null||attr.value!=='12')throw 'default clamped and detached Attr';}if(x.labels!==labels||labels[0]!==label||label.control!==x||label.form!==null||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'native metadata side effects';watch.disconnect();document.title='Meter numeric '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("Meter numeric {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],if round==0{0xcc2244}else{0x114455});let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
